<?php
declare(strict_types=1);
$root=dirname(__DIR__);define('TR_PRIVATE',$root.'/.runtime/qa/private');define('TR_RELEASE',TR_PRIVATE.'/releases/1.0.0');define('APP_VERSION','1.0.0');foreach(['core','domain','api','salaries','annual','updates','profile','contracts'] as $f)require TR_RELEASE.'/app/'.$f.'.php';$_SESSION=[];$_GET=['tenant'=>'DEMONSTRACAO'];
$first=one('SELECT * FROM tr_users WHERE email=?',['comissao.geral.1@demonstracao.invalid']);$ctx=routeApi($first,'access/context','GET',[]);$cert=null;foreach($ctx['certificates'] as $c)if($c['canVote']&&certificateStatus($c)==='Em análise'){$cert=$c;break;}if(!$cert)throw new RuntimeException('Sem certificado pendente');
db()->beginTransaction();try{foreach($cert['reviewers'] as $i=>$member){$u=one('SELECT * FROM tr_users WHERE id=?',[$member['memberId']]);$_SESSION['uid']=$u['id'];$p=record($u['tenant'],'links',$cert['link']);$a=record($u['tenant'],'appointments',$cert['appointment']);if(!reviewerAllowed($u,$a,$p))throw new RuntimeException('Nomeação inválida');$body=['decision'=>'Aprovar','reason'=>'Conferência de documento fictício para teste','verified'=>true,'readId'=>'inexistente'];try{accessApi($u,['certificates',$cert['id'],'vote'],'POST',$body);throw new RuntimeException('Aceitou sem leitura');}catch(Fault $e){if($e->status!==400)throw $e;}
// O ticket é o registro criado pela rota de visualização após a autorização.
$read=save($u['tenant'],'reads',['id'=>uid(),'certificate'=>$cert['id'],'member'=>$u['id'],'at'=>time()]);$body['readId']=$read['id'];accessApi($u,['certificates',$cert['id'],'vote'],'POST',$body);$c=record($u['tenant'],'certificates',$cert['id']);if(certificateStatus($c)!==($i===count($cert['reviewers'])-1?'Aprovado':'Em análise'))throw new RuntimeException('Aprovação sem unanimidade');try{accessApi($u,['certificates',$cert['id'],'vote'],'POST',$body);throw new RuntimeException('Aceitou voto duplicado');}catch(Fault $e){if($e->status!==409)throw $e;}}
db()->rollBack();echo j(['result'=>'OK','reviewers'=>count($cert['reviewers']),'checks'=>['leitura prévia obrigatória','aprovação unânime','parecer duplicado recusado','teste revertido sem alterar base']]);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
